		fmt.Fprintln(w, "          Additional regex patterns used to find secrets. If there is a matching group in the regex the matched group will be tested for randomness before being reported as a secret")
		fmt.Fprintln(w, "  -h, --help")
		fmt.Fprintln(w, "          Print help (see more with '--help')")
		fmt.Fprintln(w, "  -V, --version")
		fmt.Fprintln(w, "          Print version")
	} else {
		fmt.Fprintln(w, "      --install-pre-commit")
		fmt.Fprintln(w, "          Install `ripsecrets` as a pre-commit hook automatically in git directory provided")
		fmt.Fprintln(w)
		fmt.Fprintln(w, "      --strict-ignore")
		fmt.Fprintln(w, "          If you pass a path as an argument that's ignored by .secretsignore it will be scanned by default. --strict-ignore will override this behavior and not search the paths passed as arguments that are excluded by the .secretsignore file. This is useful when invoking secrets as a pre-commit")
		fmt.Fprintln(w)
		fmt.Fprintln(w, "      --only-matching")
