func parseArgs(args []string) (*config, error) {
	cfg := &config{}
	i := 0
	seenDoubleDash := false
	for i < len(args) {
		a := args[i]
		if !seenDoubleDash {
			switch a {
			case "--":
				seenDoubleDash = true
				i++
				continue
			case "-h":
				usage(os.Stdout, true)
				os.Exit(0)
			case "--help":
				usage(os.Stdout, false)
				os.Exit(0)
			case "-V", "--version":
				fmt.Println(version)
				os.Exit(0)
			case "--install-pre-commit":
				cfg.installPreCommit = true
				i++
				continue
			case "--strict-ignore":
				cfg.strictIgnore = true
				i++
				continue
			case "--only-matching":
				cfg.onlyMatching = true
				i++
				continue
			case "--additional-pattern":
				if i+1 >= len(args) {
					return nil, fmt.Errorf("a value is required for '--additional-pattern <ADDITIONAL_PATTERNS>' but none was supplied\n\nFor more information, try '--help'.")
				}
				cfg.additionalPatterns = append(cfg.additionalPatterns, args[i+1])
				i += 2
				continue
			}
			if strings.HasPrefix(a, "--additional-pattern=") {
				cfg.additionalPatterns = append(cfg.additionalPatterns, strings.TrimPrefix(a, "--additional-pattern="))
				i++
				continue
			}
			if strings.HasPrefix(a, "--") || (strings.HasPrefix(a, "-") && a != "-") {
				return nil, fmt.Errorf("unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: executable [OPTIONS] [Source files]...\n\nFor more information, try '--help'.", a, a, a)
			}
		}
		cfg.sourceFiles = append(cfg.sourceFiles, a)
		i++
	}
	return cfg, nil
}

func main() {
	cfg, err := parseArgs(os.Args[1:])
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(2)
	}

	if cfg.installPreCommit {
		dir := "."
		if len(cfg.sourceFiles) > 0 {
			dir = cfg.sourceFiles[0]
		}
		if err := installPreCommit(dir); err != nil {
			fmt.Fprintln(os.Stderr, "Error:", err)
			os.Exit(2)
		}
		// If multiple paths given, try to install in each
		for _, d := range cfg.sourceFiles[1:] {
			if err := installPreCommit(d); err != nil {
				fmt.Fprintln(os.Stderr, "Error:", err)
				os.Exit(2)
			}
		}
		os.Exit(0)
	}

	if len(cfg.sourceFiles) == 0 {
		cfg.sourceFiles = []string{"."}
	}

	additionalRegexes, err := compileAdditional(cfg.additionalPatterns)
	if err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(2)
	}

	ignoreInfo := loadSecretsIgnore(".")

	foundAny := false
	var mu sync.Mutex

	var wg sync.WaitGroup
	sem := make(chan struct{}, 8)

	processFile := func(path string, displayPath string, fromCmdArg bool) {
		defer wg.Done()
		sem <- struct{}{}
		defer func() { <-sem }()

		// Skip if in strict-ignore mode and path matches secretsignore
		if cfg.strictIgnore && ignoreInfo.pathMatches(path) {
			return
		}
		// Skip if from auto-walk (not cmd arg) and path matches ignores
		if !fromCmdArg {
			if ignoreInfo.pathMatches(path) {
				return
			}
		}

		matches := scanFile(path, additionalRegexes, ignoreInfo, cfg.onlyMatching)
		if len(matches) > 0 {
			mu.Lock()
			foundAny = true
			for _, m := range matches {
				fmt.Printf("%s:%d:%s\n", displayPath, m.lineNum, m.text)
			}
			mu.Unlock()
		}
	}

	for _, src := range cfg.sourceFiles {
		info, err := os.Stat(src)
		if err != nil {
			fmt.Fprintf(os.Stderr, "%s: %s\n", src, formatOSError(err))
			continue
		}
		if info.IsDir() {
			walkDir(src, ignoreInfo, func(path string) {
				// Compute display path relative to src, but use "./..." form
				dp := displayPath(src, path)
				wg.Add(1)
				go processFile(path, dp, false)
			})
		} else {
			// Direct file argument
			if cfg.strictIgnore && ignoreInfo.pathMatches(src) {
				continue
			}
			wg.Add(1)
			go processFile(src, src, true)
		}
	}

	wg.Wait()

	if foundAny {
		os.Exit(1)
	}
	os.Exit(0)
}

func formatOSError(err error) string {
	// Mimic rust io::Error format
	if errors.Is(err, os.ErrNotExist) {
		return "No such file or directory (os error 2)"
	}
	if errors.Is(err, os.ErrPermission) {
		return "Permission denied (os error 13)"
	}
	return err.Error()
}

func displayPath(root, path string) string {
	if root == "." {
		return "./" + strings.TrimPrefix(path, "./")
	}
	// if root was given without trailing slash, and path starts with root, use path as-is
	return path
}

func compileAdditional(pats []string) ([]*regexp.Regexp, error) {
	var regexes []*regexp.Regexp
	for _, p := range pats {
		r, err := regexp.Compile(p)
		if err != nil {
			return nil, err
		}
		regexes = append(regexes, r)
	}
	return regexes, nil
}

func installPreCommit(dir string) error {
	gitDir := filepath.Join(dir, ".git")
	info, err := os.Stat(gitDir)
	if err != nil || !info.IsDir() {
		return fmt.Errorf(".git directory not found")
	}
	hookDir := filepath.Join(gitDir, "hooks")
	if err := os.MkdirAll(hookDir, 0755); err != nil {
		return err
	}
	hookPath := filepath.Join(hookDir, "pre-commit")
	hookLine := "ripsecrets --strict-ignore `git diff --cached --name-only --diff-filter=ACM`\n"

	var existing []byte
	if data, err := os.ReadFile(hookPath); err == nil {
		existing = data
	}
	if strings.Contains(string(existing), "ripsecrets") {
		return fmt.Errorf("pre-commit hook has already been installed")
	}
	var newContent []byte
	if len(existing) == 0 {
		newContent = []byte(hookLine)
	} else {
		needLF := len(existing) > 0 && existing[len(existing)-1] != '\n'
		if needLF {
			existing = append(existing, '\n')
		}
		newContent = append(existing, []byte(hookLine)...)
	}
	if err := os.WriteFile(hookPath, newContent, 0755); err != nil {
		return err
	}
	if err := os.Chmod(hookPath, 0755); err != nil {
		return err
	}
	return nil
}

type match struct {
	lineNum int
	text    string
}

func scanFile(path string, additional []*regexp.Regexp, ignoreInfo *ignoreSet, onlyMatching bool) []match {
	f, err := os.Open(path)
	if err != nil {
		return nil
	}
	defer f.Close()

	// Check for binary file: read first 8KB, look for null byte at start  
	head := make([]byte, 8)
	n, _ := f.Read(head)
	if n > 0 && head[0] == 0 {
		return nil
	}
	f.Seek(0, 0)

	var matches []match
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 64*1024), 1024*1024)
	lineNum := 0
	for scanner.Scan() {
		lineNum++
		rawLine := scanner.Bytes()
		// Replace null bytes with space (like ripgrep)
		line := make([]byte, len(rawLine))
		for i, b := range rawLine {
			if b == 0 {
				line[i] = ' '
			} else {
				line[i] = b
			}
		}
		lineStr := string(line)

		var lineMatches []string
		for _, sec := range findSecrets(lineStr, additional) {
			if ignoreInfo.secretIgnored(sec) {
				continue
			}
			lineMatches = append(lineMatches, sec)
		}

		if len(lineMatches) == 0 {
			continue
		}

		if onlyMatching {
			for _, lm := range lineMatches {
				matches = append(matches, match{lineNum, lm})
			}
		} else {
			matches = append(matches, match{lineNum, lineStr})
		}
	}
	return matches
}

// ignoreSet parses .secretsignore-style file
type ignoreSet struct {
	pathPatterns []string
	secrets      map[string]bool
	baseDir      string
}

func (is *ignoreSet) pathMatches(path string) bool {
	rel, err := filepath.Rel(is.baseDir, path)
	if err != nil {
		rel = path
	}
	for _, p := range is.pathPatterns {
		if matchGitIgnore(p, rel) {
			return true
		}
	}
	return false
}

func (is *ignoreSet) secretIgnored(s string) bool {
	if is == nil || is.secrets == nil {
		return false
	}
	return is.secrets[s]
}

func matchGitIgnore(pattern, path string) bool {
	if pattern == "" {
		return false
	}
	// Simple matching: exact, or prefix, or suffix
	if pattern == path {
		return true
	}
	if matched, _ := filepath.Match(pattern, path); matched {
		return true
	}
	if matched, _ := filepath.Match(pattern, filepath.Base(path)); matched {
		return true
	}
	// Check if path starts with pattern
	if strings.HasPrefix(path, pattern+"/") {
		return true
	}
	return false
}

func loadSecretsIgnore(baseDir string) *ignoreSet {
	is := &ignoreSet{baseDir: baseDir, secrets: map[string]bool{}}
	data, err := os.ReadFile(filepath.Join(baseDir, ".secretsignore"))
	if err != nil {
		return is
	}
	lines := strings.Split(string(data), "\n")
	inSecrets := false
	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if line == "[secrets]" {
			inSecrets = true
			continue
		}
		if strings.HasPrefix(line, "[") {
			inSecrets = false
			continue
		}
		if inSecrets {
			is.secrets[line] = true
		} else {
			is.pathPatterns = append(is.pathPatterns, line)
		}
	}
	return is
}

// walkDir walks directory honoring .gitignore and hidden files
func walkDir(root string, ignoreInfo *ignoreSet, visit func(string)) {
	gitignores := loadGitignoreStack(root)
	var walk func(dir string) 
	walk = func(dir string) {
		entries, err := os.ReadDir(dir)
		if err != nil {
			return
		}
		for _, e := range entries {
			name := e.Name()
			if strings.HasPrefix(name, ".") {
				continue
			}
			full := filepath.Join(dir, name)
			// Check gitignore
			rel, _ := filepath.Rel(root, full)
			if matchIgnoreStack(gitignores, rel, e.IsDir()) {
				continue
			}
			// Check secretsignore
			if ignoreInfo.pathMatches(full) {
				continue
			}
			if e.IsDir() {
				walk(full)
			} else {
				visit(full)
			}
		}
	}
	walk(root)
}

type gitignoreStack struct {
	patterns []string
}

func loadGitignoreStack(root string) *gitignoreStack {
	s := &gitignoreStack{}
	// Simple: load root/.gitignore
	data, err := os.ReadFile(filepath.Join(root, ".gitignore"))
	if err == nil {
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(line)
			if line == "" || strings.HasPrefix(line, "#") {
				continue
			}
			s.patterns = append(s.patterns, line)
		}
	}
	return s
}

func matchIgnoreStack(s *gitignoreStack, relPath string, isDir bool) bool {
	for _, p := range s.patterns {
		if matchGitIgnore(p, relPath) {
			return true
		}
	}
	return false
}

