package main

import (
	"math"
	"regexp"
	"strings"
)

// Known secret regexes
var knownPatterns = []*regexp.Regexp{
	// GitHub personal access tokens
	regexp.MustCompile(`gh[oprsu]_[A-Za-z0-9_]{36,255}`),
	// Stripe live secret/restricted keys
	regexp.MustCompile(`(?:sk|rk)_live_[0-9a-zA-Z]{24,}`),
	// Google API key
	regexp.MustCompile(`AIzaSy[A-Za-z0-9_\-]{33,}`),
	// Slack legacy tokens
	regexp.MustCompile(`xox[abopsr]-[0-9]+-[0-9a-zA-Z]+(?:-[0-9a-zA-Z]+)*`),
	// Slack webhook URL
	regexp.MustCompile(`https://hooks\.slack\.com/services/T[A-Za-z0-9_]+/B[A-Za-z0-9_]+/[A-Za-z0-9_]+`),
	// NPM tokens
	regexp.MustCompile(`npm_[A-Za-z0-9]{36}`),
	// GitLab personal access tokens
	regexp.MustCompile(`glpat-[A-Za-z0-9_\-]{20}`),
	// SendGrid
	regexp.MustCompile(`SG\.[A-Za-z0-9_\-]{22}\.[A-Za-z0-9_\-]{43,}`),
	// Twilio
	regexp.MustCompile(`(?:SK|AC)[a-f0-9]{32}`),
	// Square CSP
	regexp.MustCompile(`sq0csp-[A-Za-z0-9_\-]{40,}`),
	// JWT
	regexp.MustCompile(`eyJ[A-Za-z0-9_\-]+\.[A-Za-z0-9_\-]{3,}(?:\.[A-Za-z0-9_\-]*)*`),
	// PEM private keys
	regexp.MustCompile(`-----BEGIN [A-Z ]*PRIVATE KEY[A-Z ]*-----`),
}

// The secret identifier name regex - word that contains key|secret|password|token
// Combined with value extraction

// Generic "assignment" regex: something like `<word containing secret-like name>\s*[=:]\s*(['"])?<value>\1?`
// Match group captures the value.
var assignmentRegex = regexp.MustCompile(`[A-Za-z0-9_\-]*(?i:key|secret|password|token)[A-Za-z0-9_\-]*(?:["']\s*|\s+)?\s*[:=]\s*(?:"([^"\n]+)"|'([^'\n]+)'|([A-Za-z0-9_\-\./]+))`)

// The "obviously high-entropy" value regexes (these override any entropy check)
var obviousSecretPatterns = []*regexp.Regexp{
	// All upper alnum 16+
	regexp.MustCompile(`\b[A-Z0-9]{16,}\b`),
	// Hex 16+
	regexp.MustCompile(`\b[a-fA-F0-9]{16,}\b`),
}

// findSecrets finds all secret matches in a line.
func findSecrets(line string, additional []*regexp.Regexp) []string {
	var out []string
	seen := map[string]bool{}
	add := func(s string) {
		if s == "" || seen[s] {
			return
		}
		seen[s] = true
		out = append(out, s)
	}

	// Known patterns
	for _, re := range knownPatterns {
		for _, m := range re.FindAllString(line, -1) {
			add(m)
		}
	}

	// Assignment regex - extract value and test randomness
	for _, m := range assignmentRegex.FindAllStringSubmatch(line, -1) {
		val := m[1]
		if val == "" {
			val = m[2]
		}
		if val == "" {
			val = m[3]
		}
		if val == "" {
			continue
		}
		if len(val) < 15 {
			continue
		}
		if isRandom(val) {
			add(val)
		}
	}

	// Additional patterns
	for _, re := range additional {
		for _, m := range re.FindAllStringSubmatchIndex(line, -1) {
			full := line[m[0]:m[1]]
			if len(m) >= 4 && m[2] >= 0 {
				// Has capture group
				cap1 := line[m[2]:m[3]]
				if isRandom(cap1) {
					add(full)
				}
			} else {
				add(full)
			}
		}
	}

	return out
}

// isRandom tests whether a string is likely a high-entropy secret.
func isRandom(s string) bool {
	if len(s) < 15 {
		return false
	}
	// Pattern 1: [A-Z0-9]{16,} 
	if len(s) >= 16 && matchesCharClass(s, isUpperOrDigit) {
		return true
	}
	// Pattern 2: [a-fA-F0-9]{16,}  (hex)
	if len(s) >= 16 && matchesCharClass(s, isHexChar) {
		return true
	}
	// Pattern 3: [0-9]{16,} 
	if len(s) >= 16 && matchesCharClass(s, isDigit) {
		return true
	}
	// Mixed: needs to pass entropy test
	return shannonBits(s) >= 3.5 && distinctCount(s) >= 10 && !hasLongSequence(s)
}

func matchesCharClass(s string, fn func(byte) bool) bool {
	for i := 0; i < len(s); i++ {
		if !fn(s[i]) {
			return false
		}
	}
	return true
}

func isUpperOrDigit(b byte) bool { return (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') }
func isHexChar(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}
func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func shannonBits(s string) float64 {
	counts := map[byte]int{}
	for i := 0; i < len(s); i++ {
		counts[s[i]]++
	}
	n := float64(len(s))
	h := 0.0
	for _, c := range counts {
		p := float64(c) / n
		h -= p * math.Log2(p)
	}
	return h
}

func distinctCount(s string) int {
	seen := map[byte]bool{}
	for i := 0; i < len(s); i++ {
		seen[s[i]] = true
	}
	return len(seen)
}

func hasLongSequence(s string) bool {
	// Check if s contains a run of 5+ sequential alphanum characters
	if len(s) < 5 {
		return false
	}
	run := 1
	for i := 1; i < len(s); i++ {
		if s[i] == s[i-1]+1 {
			run++
			if run >= 6 {
				return true
			}
		} else {
			run = 1
		}
	}
	return false
}

// removeQuotes trims surrounding quotes if paired
func trimPairedQuotes(s string) string {
	if len(s) >= 2 {
		first := s[0]
		last := s[len(s)-1]
		if (first == '"' || first == '\'') && first == last {
			return s[1 : len(s)-1]
		}
	}
	return s
}

