					add(full)
				}
			} else {
				add(full)
			}
		}
	}

	return out
}

// isRandom tests whether a string looks like a high-entropy secret.
func isRandom(s string) bool {
	if len(s) < 15 {
		return false
	}
	unique := distinctCount(s)
	if unique < 3 {
		return false
	}
	ent := shannonBits(s)
	if ent < 2.5 {
		return false
	}

	hasUpper, hasLower, hasDigit, _ := classesOf(s)

	// Class 1: All uppercase + digit (e.g. AWS-style)
	if len(s) >= 16 && matchesCharClass(s, isUpperOrDigit) && unique >= 5 {
		return true
	}
	// Class 2: Hex (case insensitive)
	if len(s) >= 16 && matchesCharClass(s, isHexChar) && unique >= 5 {
		return true
	}
	// Class 3: All digits
	if len(s) >= 16 && matchesCharClass(s, isDigit) && unique >= 5 {
		return true
	}

	mix := 0
	if hasUpper {
		mix++
	}
	if hasLower {
		mix++
	}
	if hasDigit {
		mix++
	}
	// Mixed-class: at least 2 classes, sufficient entropy and uniqueness
	if mix >= 2 && ent >= 3.5 && unique >= float64(len(s))*0.5 && !hasLongSequentialRun(s, 4) {
		return true
	}

	return false
}

func classesOf(s string) (hasUpper, hasLower, hasDigit, hasSpecial bool) {
	for i := 0; i < len(s); i++ {
		b := s[i]
		switch {
		case b >= 'A' && b <= 'Z':
			hasUpper = true
		case b >= 'a' && b <= 'z':
			hasLower = true
		case b >= '0' && b <= '9':
			hasDigit = true
		default:
			hasSpecial = true
		}
	}
	return
}

func matchesCharClass(s string, fn func(byte) bool) bool {
	for i := 0; i < len(s); i++ {
		if !fn(s[i]) {
			return false
		}
	}
	return true
}

func isUpperOrDigit(b byte) bool { return (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') }
func isHexChar(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}
func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func shannonBits(s string) float64 {
	counts := map[byte]int{}
	for i := 0; i < len(s); i++ {
		counts[s[i]]++
	}
	n := float64(len(s))
	h := 0.0
	for _, c := range counts {
		p := float64(c) / n
		h -= p * math.Log2(p)
	}
	return h
}

func distinctCount(s string) int {
	seen := map[byte]bool{}
	for i := 0; i < len(s); i++ {
		seen[s[i]] = true
	}
	return len(seen)
}

func hasLongSequentialRun(s string, n int) bool {
	if len(s) < n {
		return false
	}
	run := 1
	for i := 1; i < len(s); i++ {
		a := s[i-1]
		b := s[i]
		if b == a+1 && sameClass(a, b) {
			run++
			if run >= n {
				return true
			}
		} else {
			run = 1
		}
	}
	return false
}

func sameClass(a, b byte) bool {
	return (isUpperByte(a) && isUpperByte(b)) ||
		(isLowerByte(a) && isLowerByte(b)) ||
		(isDigit(a) && isDigit(b))
}

func isLowerByte(b byte) bool { return b >= 'a' && b <= 'z' }
func isUpperByte(b byte) bool { return b >= 'A' && b <= 'Z' }
