		// Replace ** with placeholder, use custom match
		return matchGlobStar(pattern, path)
	}
	ok, _ := filepath.Match(pattern, path)
	return ok
}

func matchGlobStar(pattern, path string) bool {
	// Naive: split on **
	parts := strings.Split(pattern, "**")
	if len(parts) == 1 {
		ok, _ := filepath.Match(pattern, path)
		return ok
	}
