package main

import (
	"math"
	"regexp"
)

// Known secret regexes - high confidence
var knownPatterns = []*regexp.Regexp{
	regexp.MustCompile(`gh[oprsu]_[A-Za-z0-9_]{36,}`),
	regexp.MustCompile(`(?:sk|rk)_live_[0-9a-zA-Z]{24,}`),
	regexp.MustCompile(`AIzaSy[A-Za-z0-9_\-]{33,}`),
	regexp.MustCompile(`xox[abopsr]-[0-9]+-[0-9a-zA-Z]+(?:-[0-9a-zA-Z]+)+`),
	regexp.MustCompile(`https://hooks\.slack\.com/services/T[A-Za-z0-9_]+/B[A-Za-z0-9_]+/[A-Za-z0-9_]+`),
	regexp.MustCompile(`npm_[A-Za-z0-9]{36}`),
	regexp.MustCompile(`glpat-[A-Za-z0-9_\-]{20}`),
	regexp.MustCompile(`SG\.[A-Za-z0-9_\-]{22}\.[A-Za-z0-9_\-]{43,}`),
	regexp.MustCompile(`(?:SK|AC)[a-f0-9]{32}`),
	regexp.MustCompile(`sq0csp-[A-Za-z0-9_\-]{40,}`),
	regexp.MustCompile(`eyJ[A-Za-z0-9_\-]+\.[A-Za-z0-9_\-]{3,}(?:\.[A-Za-z0-9_\-]*)*`),
	regexp.MustCompile(`-----BEGIN [A-Z ]*PRIVATE KEY[A-Z ]*-----`),
}

// Assignment regex - captures value after variable name containing key/secret/password/token
// Supports quoted and unquoted values; unquoted uses alnum only.
var assignmentRegex = regexp.MustCompile(`(?i)[A-Za-z0-9_\-]*(?:key|secret|password|token)[A-Za-z0-9_\-]*["']?\s*[:=]\s*(?:"([^"\n]+)"|'([^'\n]+)'|([A-Za-z0-9]+))`)

func findSecrets(line string, additional []*regexp.Regexp) []string {
	var out []string
	seen := map[string]bool{}
	add := func(s string) {
		if s == "" || seen[s] {
			return
		}
		seen[s] = true
		out = append(out, s)
	}

	for _, re := range knownPatterns {
		for _, m := range re.FindAllString(line, -1) {
			add(m)
		}
	}

	for _, m := range assignmentRegex.FindAllStringSubmatch(line, -1) {
		val := m[1]
		if val == "" {
			val = m[2]
		}
		if val == "" {
			val = m[3]
		}
		if val == "" {
			continue
		}
		if isRandom(val) {
			add(val)
		}
	}

	for _, re := range additional {
		for _, m := range re.FindAllStringSubmatchIndex(line, -1) {
			full := line[m[0]:m[1]]
			if len(m) >= 4 && m[2] >= 0 {
				cap1 := line[m[2]:m[3]]
				if isRandom(cap1) {
					add(full)
				}
			} else {
				add(full)
			}
		}
	}

	return out
}

func isRandom(s string) bool {
	if len(s) < 15 {
		return false
	}
	unique := distinctCount(s)
	if unique < 3 {
		return false
	}
	ent := shannonBits(s)
	if ent < 2.5 {
		return false
	}

	hasUpper, hasLower, hasDigit, _ := classesOf(s)

	// Class 1: All uppercase + digit
	if len(s) >= 16 && matchesCharClass(s, isUpperOrDigit) && unique >= 5 {
		return true
	}
	// Class 2: Hex (case insensitive)
	if len(s) >= 16 && matchesCharClass(s, isHexChar) && unique >= 5 {
		return true
	}
	// Class 3: All digits
	if len(s) >= 16 && matchesCharClass(s, isDigit) && unique >= 5 {
		return true
	}

	mix := 0
	if hasUpper {
		mix++
	}
	if hasLower {
		mix++
	}
	if hasDigit {
		mix++
	}
	// Mixed-class
	if mix >= 2 && len(s) >= 16 && ent >= 3.5 && float64(unique) >= float64(len(s))*0.5 {
		if hasUpper && hasLower && !hasDigit {
			return false
		}
		if hasLower && hasDigit && !hasUpper {
			if longestAlphaRun(s) >= 5 {
				return false
			}
		}
		return true
	}

	return false
}

func classesOf(s string) (hasUpper, hasLower, hasDigit, hasSpecial bool) {
	for i := 0; i < len(s); i++ {
		b := s[i]
		switch {
		case b >= 'A' && b <= 'Z':
			hasUpper = true
		case b >= 'a' && b <= 'z':
			hasLower = true
		case b >= '0' && b <= '9':
			hasDigit = true
		default:
			hasSpecial = true
		}
	}
	return
}

func matchesCharClass(s string, fn func(byte) bool) bool {
	for i := 0; i < len(s); i++ {
		if !fn(s[i]) {
			return false
		}
	}
	return true
}

func isUpperOrDigit(b byte) bool { return (b >= 'A' && b <= 'Z') || (b >= '0' && b <= '9') }
func isHexChar(b byte) bool {
	return (b >= '0' && b <= '9') || (b >= 'a' && b <= 'f') || (b >= 'A' && b <= 'F')
}
func isDigit(b byte) bool { return b >= '0' && b <= '9' }

func shannonBits(s string) float64 {
	counts := map[byte]int{}
	for i := 0; i < len(s); i++ {
		counts[s[i]]++
	}
	n := float64(len(s))
	h := 0.0
	for _, c := range counts {
		p := float64(c) / n
		h -= p * math.Log2(p)
	}
	return h
}

func distinctCount(s string) int {
	seen := map[byte]bool{}
	for i := 0; i < len(s); i++ {
		seen[s[i]] = true
	}
	return len(seen)
}

func sameClass(a, b byte) bool {
	return (isUpperByte(a) && isUpperByte(b)) ||
		(isLowerByte(a) && isLowerByte(b)) ||
		(isDigit(a) && isDigit(b))
}

func isLowerByte(b byte) bool { return b >= 'a' && b <= 'z' }
func isUpperByte(b byte) bool { return b >= 'A' && b <= 'Z' }

func isAlphaByte(b byte) bool {
	return (b >= 'a' && b <= 'z') || (b >= 'A' && b <= 'Z')
}

func longestAlphaRun(s string) int {
	best := 0
	run := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !isAlphaByte(c) {
			run = 0
			continue
		}
		if i == 0 || !isAlphaByte(s[i-1]) {
			run = 1
		} else {
			prev := s[i-1]
			if c == prev+1 && sameClass(prev, c) {
				run++
			} else {
				run = 1
			}
		}
		if run > best {
			best = run
		}
	}
	return best
}

func digitCount(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		if isDigit(s[i]) {
			n++
		}
	}
	return n
}
GOEOF
